function sf_has_table(string $t): bool { static $ok=[]; if(!isset($ok[$t])){ try { $ok[$t]=(bool)db()->query('SHOW TABLES LIKE '.db()->quote($t))->fetchColumn(); } catch(Throwable $ex){ $ok[$t]=false; } } return $ok[$t]; }
function sf_btn_style(string $x): string { return in_array($x,['primary','outline','dark'],true)?$x:'primary'; }
