// Fallback error page: instead of a blank "HTTP 500" the admin sees what exactly failed and where.
set_exception_handler(function(Throwable $ex){
  if(!headers_sent()){ http_response_code(500); echo '<!doctype html><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:900px;margin:2em auto;padding:1em;border:1px solid #e44;border-radius:8px}code{background:#fee;padding:0 3px}</style>'; }
  echo '<h2>Ошибка панели управления</h2><p><b>'.htmlspecialchars($ex->getMessage()).'</b></p><p>Файл: <code>'.htmlspecialchars($ex->getFile()).':'.$ex->getLine().'</code></p><pre style="white-space:pre-wrap;font-size:12px">'.htmlspecialchars($ex->getTraceAsString()).'</pre><p><a href="'.url('admin').'">← Вернуться в панель</a></p>';
  error_log('admin.php fatal: '.$ex->getMessage().' @ '.$ex->getFile().':'.$ex->getLine());
});
